import {CORE_MARKET_IDS,asianProbabilities,countGrid} from './market-model.mjs';
const groups={goals:'Sonuç / gol / handikap',score:'Tam skor',corners:'Korner',cards:'Sarı kart',reds:'Kırmızı kart',shots:'Şut',sot:'İsabetli şut',fouls:'Faul',offsides:'Ofsayt'};
function run(s){if(s.state===null)return 'Bilinmiyor';const prefix=s.rightCensored?'≥':'';
 if(/Over|Under/.test(s.id)){const isOver=s.id.includes('Over');return `${prefix}${s.streak} maç ${s.state===isOver?'ÜST':'ALT'}`;}
 const result={win:s.state?'galibiyet':'maç kazanamadı',draw:s.state?'beraberlik':'maç berabere kalmadı',loss:s.state?'mağlubiyet':'maç yenilmedi',unbeaten:s.state?'maç yenilmedi':'mağlubiyet',score:s.state?'maç gol attı':'maç gol atamadı',cleanSheet:s.state?'maç gol yemedi':'maç gol yedi',btts:s.state?'maç KG VAR':'maç KG YOK'};return `${prefix}${s.streak} ${result[s.id]??('maç '+(s.state?'var':'yok'))}`;
}
export function marketSummaryHtml(analysis,target,{esc,pct}={}){if(!analysis)return '';
 return `<section class="card spaced market-summary"><div class="card-title"><h2>Seriler, kadrodan sonra ikinci katman</h2><button class="text-button" data-view="markets">${analysis.rows.length} pazarı incele ↗</button></div><div class="table-wrap"><table><thead><tr><th>ARŞİV SERİSİ</th><th>${esc(target.home.name)}</th><th>${esc(target.away.name)}</th></tr></thead><tbody>${['win','totalUnder2.5','btts'].map(id=>{const r=analysis.rows.find(r=>r.id===id);return `<tr><td>${esc(r.label)}</td><td>${esc(run(r.home))}</td><td>${esc(run(r.away))}</td></tr>`;}).join('')}</tbody></table></div><p class="inline-note">Seriler, maç öncesi GBDT girdileridir; kendiliğinden devam / tersine dönüş varsayılmaz. Tam tabloda veri kapsamını, gözlenen sıklıkları ve model olasılıklarını ayrı inceleyin.</p></section>`;
}
export function marketHtml(analysis,{esc,number,pct,id='market-overview',simulationProbabilities=null}={}){
 if(!analysis)return '';const simulation=new Map((simulationProbabilities??[]).map(p=>[p.id,p]));
 const rows=analysis.rows.map(r=>({...r,probability:simulation.has(r.id)?simulation.get(r.id).home:r.probability,probabilityAway:simulation.has(r.id)?simulation.get(r.id).away:r.probabilityAway}));
 const core=r=>CORE_MARKET_IDS.includes(r.id);
 return `<section class="card spaced market-panel" id="${id}"><div class="card-title"><h2>Tekrar eden istatistikler ve pazarlar</h2><button class="text-button" data-view="market-network">Bağlantı ağını aç ↗</button><span class="tag">${rows.length} PAZAR · 60 MAÇA KADAR</span></div><p class="inline-note">Seri penceresi son 5/10 seçiminden bağımsızdır. Arşivdeki son 60 maçta seri, son 30 maçta gözlenen sıklık gösterilir. “≥” arşiv sınırına ulaşan seridir; eksik metrik seriyi keser. Arşivin aradaki tüm maçları kapsadığı doğrulanmadıkça seriler kesin tam kayıt sayılmaz.</p><p class="inline-note">${esc(analysis.note)} ${simulationProbabilities?'Gol/sonuç olasılıkları bu simülasyonun frekanslarıdır. Diğer istatistik pazarları ayrı sayım modelinden gelir.':'Gol/sonuç olasılıkları seçilen skor modelinden gelir.'} Sıklık ve tahmin olasılığı farklı ölçümlerdir.</p><label class="market-filter">Pazar grubu<select data-market-filter><option value="core">Öne çıkanlar</option><option value="all">Tüm mevcut pazarlar</option>${Object.entries(groups).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><div class="table-wrap market-table"><table><thead><tr><th>PAZAR · TAKIM PERSPEKTİFİ</th><th>EV / SERİ</th><th>DEP / SERİ</th><th>EV / GÖZLEM</th><th>DEP / GÖZLEM</th><th>EV / OLASILIK</th><th>DEP / OLASILIK</th></tr></thead><tbody>${rows.map(r=>`<tr data-market-group="${r.group}" data-market-core="${core(r)}" ${core(r)?'':'hidden'}><td>${esc(r.label)}<small>${r.method==='stat-poisson-unvalidated'?'Ayrı istatistik Poisson · kalibre edilmedi':r.method==='unavailable'?'Yeterli veri / model yok':simulation.has(r.id)?'10.000 simülasyon frekansı':'Seçili skor modeli'}</small></td><td>${esc(run(r.home))}</td><td>${esc(run(r.away))}</td><td>${r.home.known?`${r.home.successes}/${r.home.known} · ${pct(r.home.frequency)}`:'—'}</td><td>${r.away.known?`${r.away.successes}/${r.away.known} · ${pct(r.away.frequency)}`:'—'}</td><td>${pct(r.probability)}</td><td>${pct(r.probabilityAway)}</td></tr>`).join('')}</tbody></table></div><details class="asian-calculator"><summary>Asya handikap / gol çizgisi hesapla</summary><p class="inline-note">Çeyrek çizgiler iki komşu yarım çizgiye bölünür. Tam / yarım kazanma, iade ve kaybetme ihtimalleri ayrı hesaplanır. Oran veya kazanç değeri varsayılmaz.</p><div class="market-calculator-controls"><label>Veri<select data-asian-family><option value="goals">Gol</option>${Object.keys(analysis.statModels??{}).map(k=>`<option value="${k}">${esc(groups[k]??k)}</option>`).join('')}</select></label><label>Tip<select data-asian-kind><option value="handicap">Ev takımı handikap</option><option value="over">Toplam üst</option><option value="under">Toplam alt</option></select></label><label>Çizgi<input data-asian-line type="number" step="0.25" min="-50" max="50" value="-0.25"></label><button class="button ghost" data-asian-run>Hesapla</button></div><p data-asian-output role="status"></p></details><details><summary>Veri veya model eksik olan pazarlar</summary><p class="inline-note">${analysis.unavailable.map(esc).join('<br>')}</p><p class="inline-note">Geçmiş maçın sonucunu, sonradan görülen sakatlık bilgisini veya canlı olayları maç öncesi eğitim girdisi olarak kullanmayız. Modelin çıktısı kesin skor veya kazanç garantisi değildir.</p></details></section>`;
}
export function bindMarketPanels(root,analysis,goalGrid,{pct}={}){
 if(!analysis)return;for(const panel of root.querySelectorAll('.market-panel')){
  panel.querySelector('[data-market-filter]').onchange=e=>{for(const row of panel.querySelectorAll('[data-market-group]'))row.hidden=e.target.value==='core'?row.dataset.marketCore!=='true':e.target.value!=='all'&&e.target.value!==row.dataset.marketGroup;};
  panel.querySelector('[data-asian-run]').onclick=()=>{const output=panel.querySelector('[data-asian-output]');try{
   const family=panel.querySelector('[data-asian-family]').value,kind=panel.querySelector('[data-asian-kind]').value,line=Number(panel.querySelector('[data-asian-line]').value);
   if(!Number.isFinite(line)||Math.abs(line)>50||kind!=='handicap'&&line<0)throw Error('Toplam çizgisi 0–50; handikap −50–50 aralığında olmalı.');
   const stat=analysis.statModels[family],grid=family==='goals'?goalGrid:stat?countGrid(stat.home,stat.away,family==='shots'?150:100):null;
   if(!grid?.length)throw Error('Bu çizgi için yeterli model / veri yok.');const p=asianProbabilities(grid,line,{kind:kind==='handicap'?'handicap':'total',under:kind==='under'});
   output.textContent=`Tam kazanma ${pct(p.fullWin)} · Yarım kazanma ${pct(p.halfWin)} · Tam iade ${pct(p.fullPush)} · Yarım kayıp ${pct(p.halfLoss)} · Tam kayıp ${pct(p.fullLoss)}`;
  }catch(e){output.textContent=e.message;}};
 }
}
